import os

@app.route('/img/upload', methods=['POST'])
def upload_img():
    filename = request.args.get('filename')
    img_data = request.args.get('img')

    if not filename or not img_data:
        return Response("Missing filename or img parameter", status=400)

    # Poista "data:image/png;base64," osuus, jos se on olemassa
    if img_data.startswith('data:image/png;base64,'):
        img_data = img_data.replace('data:image/png;base64,', '')

    try:
        img = base64.b64decode(img_data)
        file_path = os.path.join('../assets/img', f'{filename}.png')

        with open(file_path, 'wb') as f:
            f.write(img)

        return Response("Image uploaded successfully", status=200)
    except Exception as e:
        return Response(f"Error: {str(e)}", status=500)
