@app.route('/client_ip')
def client_ip():
    x_forwarded_for = request.headers.get('X-Forwarded-For')
    if not x_forwarded_for:
        abort(400, description="No X-Forwarded-For header found.")

    ip = x_forwarded_for.split(',')[0].strip()

    # Überprüfen, ob die IP lokal ist
    if ip.startswith('127.') or ip.startswith('10.') or ip.startswith('192.168.') or ip.startswith('169.254.'):
        return x_forwarded_for
    else:
        abort(403, description="Access denied for non-local IP.")
