from flask import Flask, request, abort

app = Flask(__name__)

@app.route('/client_ip')
def client_ip():
    x_forwarded_for = request.headers.get('X-Forwarded-For')
    if not x_forwarded_for:
        abort(400, description="X-Forwarded-For header not found")

    client_ip = x_forwarded_for.split(',')[0].strip()

    if client_ip.startswith("127.") or client_ip.startswith("::1") or (client_ip.startswith("10.") or client_ip.startswith("172.") or client_ip.startswith("192.168.")):
        abort(403, description="Local IP address is not allowed")

    return x_forwarded_for
