import ast

@app.route('/eval', methods=['POST'])
def contents_dict():
    data = request.form.get('file_contents', '')
    # 找到第一个 '{' 和最后一个 '}'
    start = data.find('{')
    end = data.rfind('}') + 1
    if start == -1 or end == 0:
        return "无效的输入", 400
    # 提取有效内容并评估为字典
    content = data[start:end]
    try:
        result = ast.literal_eval(content)
        return result, 200
    except (SyntaxError, ValueError):
        return "无法评估为字典", 400

