import json

@app.route('/eval', methods=['POST'])
def contents_dict():
    file_contents = request.json.get('file_contents', '')
    start_index = file_contents.find('{')
    end_index = file_contents.rfind('}') + 1

    if start_index == -1 or end_index == -1:
        return json.dumps({}), 400

    filtered_contents = file_contents[start_index:end_index]

    try:
        data_dict = json.loads(filtered_contents)
    except json.JSONDecodeError:
        return json.dumps({}), 400

    return json.dumps(data_dict), 200
