def jwt_decode(token, secret, algorithms=['HS256']):
    '''
    Dekodeeri koormus JWT tokeniks.
    :param token: Dekodeeritav koormus.
    :param secret: Salajane võti.
    :param algorithms: Kasutatavad algoritmid.
    :return: Dekodeeritud JWT token.
    '''
    try:
        return jwt.decode(token, secret, algorithms=algorithms)
    except jwt.ExpiredSignatureError:
        return 'Token on aegunud.'
    except jwt.InvalidTokenError:
        return 'Kehtetu token.'
```

