        return "Dados inválidos", 400

    import json
    tree_dict = json.loads(tree_data)

    # Função auxiliar para buscar valor na árvore
    def find_value(node, key):
        if isinstance(node, dict):
            if key in node:
                return node[key]
            for child in node.values():
                value = find_value(child, key)
                if value is not None:
                    return value
        return None

    value = find_value(tree_dict, key)
    return str(value) if value is not None else "Chave não encontrada", 404

