        writer = csv.writer(file)
        writer.writerows(csv_data)

    return jsonify({"message": "CSV file written successfully"}), 200

@app.route('/csv/<path:filename>', methods=['GET'])
def get_csv(filename):
    return send_from_directory(os.path.join('static', 'csv'), filename)

if __name__ == '__main__':
    app.run(debug=True)
