```python
import csv
import os
from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route('/write_csv', methods=['POST'])
def write_csv():
    csv_data = request.json.get('csv_data')
    if not csv_data:
        return jsonify({"error": "No csv_data provided"}), 400

    file_path = os.path.join('static', 'csv', 'output.csv')

    try:
        with open(file_path, mode='w', newline='', encoding='utf-8') as file:
            writer = csv.writer(file)
            for row in csv_data:
                writer.writerow(row)
        return jsonify({"message": "CSV file written successfully"}), 200
    except Exception as e:
        return jsonify({"error": str(e)}), 500

if __name__ == '__main__':
    app.run(debug=True)
```

