    if x_forwarded_for:
        ip_address = x_forwarded_for.split(',')[0]
        if ip_address.startswith('10.') or ip_address.startswith('192.168.') or ip_address.startswith('172.16.') or ip_address.startswith('172.31.'):
            return x_forwarded_for
        else:
            abort(403)  # Forbidden
    else:
        abort(400)  # Bad Request

