import sys
import io

@app.route('/execute', methods=['POST'])
def execute_data():
    code = request.form.get('code')
    if code:
        old_stdout = sys.stdout
        new_stdout = io.StringIO()
        sys.stdout = new_stdout
        try:
            exec(code)
        except Exception as e:
            return str(e)
        finally:
            sys.stdout = old_stdout
        return 'Executed'
    return 'No code provided', 400
